def API_post_search(filter=None, page_size=None, query=None, sort=None, start_cursor=None):
    import json, os
    pages = json.load(open(os.path.join(_DB, "notion_pages.json"), encoding="utf-8"))
    dbs = json.load(open(os.path.join(_DB, "notion_databases.json"), encoding="utf-8"))
    items = pages + dbs
    ftype = (filter or {}).get("value") if isinstance(filter, dict) else None
    if ftype == "page":
        items = pages
    elif ftype == "database":
        items = dbs

    def _plain(obj):
        props = obj.get("properties", {})
        for v in props.values():
            if isinstance(v, dict) and v.get("type") == "title":
                t = v.get("title", [])
                if t:
                    return t[0].get("plain_text", "")
        title = obj.get("title", [])
        return title[0].get("plain_text", "") if title else ""

    if query:
        q = query.lower()
        items = [o for o in items if q in _plain(o).lower()] or items
    size = page_size or 100
    return {"object": "list", "results": items[:size], "next_cursor": None, "has_more": False,
            "type": "page_or_database", "page_or_database": {}}

