def API_patch_block_children(block_id, children, after=None):
    import json, os, uuid, datetime
    now = datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%S.000Z")
    appended = []
    for ch in (children or []):
        new = dict(ch) if isinstance(ch, dict) else {}
        new.setdefault("object", "block")
        new["id"] = str(uuid.uuid4())
        new.setdefault("type", new.get("type", "paragraph"))
        new["parent"] = {"type": "block_id", "block_id": block_id}
        new["created_time"] = now
        new["last_edited_time"] = now
        new["has_children"] = False
        new["archived"] = False
        appended.append(new)
    return {"object": "list", "results": appended, "next_cursor": None, "has_more": False,
            "type": "block", "block": {}}

