def API_patch_page(page_id, archived=None, cover=None, icon=None, in_trash=None, properties=None):
    import json, os, datetime
    pages = json.load(open(os.path.join(_DB, "notion_pages.json"), encoding="utf-8"))
    target = next((p for p in pages if p.get("id") == page_id), pages[0] if pages else
                  {"object": "page", "id": page_id, "properties": {}})
    target = json.loads(json.dumps(target))
    if archived is not None:
        target["archived"] = archived
    if in_trash is not None:
        target["in_trash"] = in_trash
    if icon is not None:
        target["icon"] = icon
    if cover is not None:
        target["cover"] = cover
    if properties:
        target.setdefault("properties", {})
        for k, v in properties.items():
            target["properties"][k] = v
    target["last_edited_time"] = datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%S.000Z")
    return target

